51	+import { CONFIG } from '../../config';
52	+import { rng, clamp } from '../math';
53	+
54	+/* =====================================================================
55	+   HÌNH HỌC CÂY — cây bóng mát (spec G1) và cây dừa (spec G2), thuần (không DOM, không texture).
