63	+   Ngẫu nhiên dùng rng(seed) riêng — không gọi rand() chung.
64	+   ===================================================================== */
65	+const T = CONFIG.trees;
66	+type RGB = [number, number, number];
67	+const V = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
68	+
69	+/* Gói mảng thành BufferGeometry không index */
70	+function trGeo(p: number[], n: number[], uv: number[], c: number[]): THREE.BufferGeometry {
71	+  const g = new THREE.BufferGeometry();
72	+  g.setAttribute('position', new THREE.Float32BufferAttribute(p, 3)); g.setAttribute('normal', new THREE.Float32BufferAttribute(n, 3));
73	+  g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2)); g.setAttribute('color', new THREE.Float32BufferAttribute(c, 3));
74	+  return g;
75	+}
76	+
77	+/* Gán màu đỉnh theo hàm vị trí; bỏ index để gộp được với các phần khác */
78	+function trPaint(g: THREE.BufferGeometry, fn: (x: number, y: number, z: number) => RGB): THREE.BufferGeometry {
79	+  if (g.index) g = g.toNonIndexed();
80	+  const p = g.getAttribute('position'), c = new Float32Array(p.count * 3);
81	+  for (let i = 0; i < p.count; i++) c.set(fn(p.getX(i), p.getY(i), p.getZ(i)), i * 3);
82	+  g.setAttribute('color', new THREE.BufferAttribute(c, 3));
83	+  return g;
84	+}
85	+
86	+/* Ống hở hai đầu theo đường gấp khúc: mỗi điểm có bán kính và màu vòng.
87	+   flat = true: vòng nằm ngang (thân đứng, kể cả khi cong) ⇒ đáy đúng y = 0, đỉnh đúng cao độ điểm cuối; ngược lại vòng vuông góc với hướng ống (cành). */
88	+function trTube(path: { p: THREE.Vector3; r: number; c: RGB }[], sides: number, flat = false): THREE.BufferGeometry {
89	+  const P: number[] = [], N: number[] = [], UV: number[] = [], C: number[] = [];
90	+  const rings = path.map((s, i) => {
91	+    let A = V(1, 0, 0), B = V(0, 0, 1);
92	+    if (!flat) {
93	+      const t = path[Math.min(i + 1, path.length - 1)].p.clone().sub(path[Math.max(i - 1, 0)].p).normalize();
94	+      A = new THREE.Vector3().crossVectors(t, Math.abs(t.y) < 0.9 ? V(0, 1, 0) : V(1, 0, 0)).normalize(); B = new THREE.Vector3().crossVectors(t, A);
95	+    } else { B = V(0, 0, -1); }   // vòng ngang: (A, B, +Y) thuận tay phải để mặt quấn ra ngoài
96	+    return Array.from({ length: sides + 1 }, (_, j) => { const a = (j / sides) * Math.PI * 2, d = A.clone().multiplyScalar(Math.cos(a)).addScaledVector(B, Math.sin(a)); return { p: s.p.clone().addScaledVector(d, s.r), n: d, u: j / sides, v: i / (path.length - 1), c: s.c }; });
97	+  });
98	+  const put = (q: { p: THREE.Vector3; n: THREE.Vector3; u: number; v: number; c: RGB }) => { P.push(q.p.x, q.p.y, q.p.z); N.push(q.n.x, q.n.y, q.n.z); UV.push(q.u, q.v); C.push(...q.c); };
99	+  for (let i = 0; i < rings.length - 1; i++) for (let j = 0; j < sides; j++) {
100	+    const a = rings[i][j], b = rings[i][j + 1], c = rings[i + 1][j + 1], d = rings[i + 1][j];
101	+    put(a); put(b); put(c); put(a); put(c); put(d);
102	+  }
103	+  return trGeo(P, N, UV, C);
104	+}
105	+
106	+/* ---------- Cây bóng mát: thân + cành ---------- */
107	+/* Gốc xòe, thân thẳng tới chỗ tách (fork), 1 cành giữa gần thẳng đứng + các cành tỏa hình vòng cung; mỗi cành 2 đoạn */
108	+export function trShadeTrunkGeo(): THREE.BufferGeometry {
