+  for (let i = 0; i <= segs; i++) {
+    const t = i / segs, a = elev - droop * Math.pow(t, 1.35), w = W * Math.pow(Math.sin(Math.PI * (0.08 + 0.86 * t)), 0.6), sag = w * 0.5, v = 0.1 + 0.9 * t;
