+  };
+  for (let i = 0; i < P.staticFronds; i++) {
+    const t = i / (P.staticFronds - 1), yaw = i * 2.4 + r() * 0.3, L = S * (0.8 + 0.3 * t), elev = 0.9 - 1.0 * t, droop = 0.4 + 0.8 * t, W = 0.11 * S, k = 0.8 + r() * 0.2;
