+  for (const v of pts(trShadeCrownGeo())) { const s = Math.floor(((Math.atan2(v.z, v.x) + Math.PI) / (2 * Math.PI)) * N) % N; mx[s] = Math.max(mx[s], hr(v)); }
+  const hi = Math.max(...mx), lo = Math.min(...mx);
